const D = { billow: .62, scale: 1, energy: .6, shear: .6, speed: 1, density: .55, hue: 30, x: .5, y: .5, style: 'sky-shear', act: 'drift', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const W = width, H = height, TAU = 6.28318530718;
const clp = (v,a,b)=> v<a?a:v>b?b:v;
const ss = t => { t = t<0?0:t>1?1:t; return t*t*(3-2*t); };

// --- coarse dye grid (long side <=176), aspect-matched, size-keyed cache ---
let GW, GH;
if (W>=H){ GW=168; GH=Math.max(4,Math.round(168*H/W)); } else { GH=168; GW=Math.max(4,Math.round(168*W/H)); }
const GN = GW*GH;
if (!S.buf || S.gw!==GW || S.gh!==GH){
  S.gw=GW; S.gh=GH;
  if (S.buf && S.buf.remove) S.buf.remove();
  S.buf = createGraphics(GW,GH); S.buf.pixelDensity(1);
  S.d = new Float32Array(GN); S.d2 = new Float32Array(GN);
  const y0i = clp(P.y,0.15,0.85), thi = 0.55;
  for (let gy=0; gy<GH; gy++){
    const Yi = ((gy/GH)-y0i)*6, Ti = 0.5 - 0.5*Math.tanh(Yi/thi);
    for (let gx=0; gx<GW; gx++) S.d[gy*GW+gx]=Ti;
  }
  S.seedUsed = null;
}

// --- seed-dependent offsets (inline hash, no p5 random) ---
if (S.seedUsed !== (P.seed|0)){
  S.seedUsed = (P.seed|0);
  const fr = i => { const s = Math.sin(i*127.1 + (P.seed|0)*311.7)*43758.5453; return s-Math.floor(s); };
  S.soff = fr(1)*TAU*4; S.yoff = (fr(2)-0.5)*0.06; S.hoff = fr(3)*46;
}

// --- palette LUT (raw RGB bytes; rebuilt only on style/hue/seed change) ---
const lkey = P.style+':'+Math.round(P.hue)+':'+(P.seed|0);
if (S.lkey!==lkey){ S.lkey=lkey; S.lut = buildLUT(P.style, P.hue + (S.hoff||0), P.seed); }

// --- dynamics: instability amplitude, drift, interface meander ---
const sec = K.section|0, intn = (K.intensity!=null?K.intensity:0.6);
let Aeff = clp(P.billow,0,1)*0.92 * (0.82 + 0.18*Math.sin(K.t*0.13 + S.soff));
let driftRate = 0.22 + P.speed*0.34, meander = 0.045;
if (P.act==='build'){ Aeff *= 0.30 + 0.70*((sec%8)/7); }
else if (P.act==='storm'){ Aeff = clp(Aeff*1.25+0.12,0,0.94); driftRate *= 1.5; meander *= 1.8; }
Aeff = clp(Aeff + A.bass*0.14 + (sec%4)*0.02, 0, 0.94);
driftRate += A.lowmid*0.4;
const phase = K.t*driftRate + S.soff + P.x*TAU;
const y0 = clp(P.y + S.yoff + Math.sin(K.t*0.11)*meander + Math.sin(K.t*0.047+1.7)*meander*0.6, 0.12, 0.88);
const ySpan = 5 + P.shear*3;
const billows = clp((W>=H?(W/H):1)*2.6 / clp(P.scale,0.35,3), 1, 16);
const kx = TAU*billows;
const advGain = (10 + P.speed*16) * (0.6 + P.shear*0.9);
const th = 0.35 + (1-P.density)*0.6;
const relax = 0.02 + (1-P.density)*0.05 + (P.act==='storm'?0.02:0);

// --- semi-Lagrangian advection through Stuart cat's-eye shear field ---
const src=S.d, dst=S.d2, gyf=ySpan/GH, gxf=kx/GW;
for (let gy=0; gy<GH; gy++){
  const ny = gy/GH, Y = (ny-y0)*ySpan, cy = Math.cosh(Y), sy = Math.sinh(Y), Tt = 0.5 - 0.5*Math.tanh(Y/th);
  for (let gx=0; gx<GW; gx++){
    const xa = (gx/GW)*kx - phase, ca = Math.cos(xa), sa = Math.sin(xa);
    let den = cy + Aeff*ca; if (den<0.05) den=0.05;
    const vx = (sy/den)*gyf, vy = (Aeff*sa/den)*gxf;
    let dxs = -vx*advGain, dys = -vy*advGain;
    const mg = Math.abs(dxs)+Math.abs(dys); if (mg>4){ const s=4/mg; dxs*=s; dys*=s; }
    let bx = gx+dxs, by = gy+dys;
    if (bx<0) bx=0; else if (bx>GW-1.001) bx=GW-1.001;
    if (by<0) by=0; else if (by>GH-1.001) by=GH-1.001;
    const x0=bx|0, y0i=by|0, fx=bx-x0, fy=by-y0i, i00=y0i*GW+x0;
    const a0=src[i00], b0=src[i00+1], c0=src[i00+GW], d0=src[i00+GW+1];
    const t0=a0+(b0-a0)*fx, t1=c0+(d0-c0)*fx;
    let val = t0+(t1-t0)*fy;
    val += (Tt-val)*relax;
    dst[gy*GW+gx]=val;
  }
}

// --- render dye -> two-layer palette + edge highlight -> buffer bytes ---
S.buf.loadPixels();
const pix=S.buf.pixels, lut=S.lut;
const expo = 0.5 + P.energy*0.55 + intn*0.22 + A.rms*0.5;
const mode = P.style==='ocean-wave'?1 : P.style==='thermal'?2 : P.style==='ink-shear'?3 : P.style==='aurora'?4 : 0;
const rimG = (mode===1?2.4 : mode===2?1.0 : 0.7)*(0.4+P.energy);
const treb = A.treble;
for (let gy=0; gy<GH; gy++){
  for (let gx=0; gx<GW; gx++){
    const i=gy*GW+gx, d=dst[i];
    const rr=(gx<GW-1?dst[i+1]:d), dn=(gy<GH-1?dst[i+GW]:d);
    const edge=Math.abs(rr-d)+Math.abs(dn-d);
    let li=(d*255)|0; if(li<0)li=0; else if(li>255)li=255; const l3=li*3;
    let R=lut[l3]/255, G=lut[l3+1]/255, B=lut[l3+2]/255;
    if (mode===0){ const rim=edge*rimG*(0.7+treb*1.5); R=R*expo+rim*0.9; G=G*expo+rim*0.85; B=B*expo+rim*0.72; }
    else if (mode===1){ const foam=clp(edge*rimG*(0.8+treb*2.0),0,0.95), br=0.5+expo*0.6; R=R*br+foam; G=G*br+foam; B=B*br+foam; }
    else if (mode===2){ R=R*expo+edge*0.9; G=G*expo+edge*0.8; B=B*expo+edge*0.5; }
    else if (mode===3){ const ink=clp(edge*(2.6+treb*2)*(0.5+P.energy),0,0.85), br=expo; R=(R*br)*(1-ink); G=(G*br)*(1-ink); B=(B*br)*(1-ink); }
    else { const glow=clp(0.14 + edge*(2.6+treb*2)*(0.4+P.energy) + d*(1-d)*0.55, 0, 1.15); R=0.02+R*glow; G=0.03+G*glow; B=0.09+B*glow; }
    const o=i<<2;
    pix[o]=R<0?0:R>1?255:R*255; pix[o+1]=G<0?0:G>1?255:G*255; pix[o+2]=B<0?0:B>1?255:B*255; pix[o+3]=255;
  }
}
S.buf.updatePixels();
S.d=dst; S.d2=src;

push();
if (P.alpha<100) tint(0,0,100,P.alpha);
image(S.buf, 0,0, W,H);
pop();

// audio veil ON TOP (partial, never full-frame flash; zero during validation)
if (P.alpha>=100 && (A.rms>0.02 || A.bass>0.02)){
  push(); blendMode(ADD); noStroke();
  fill(((P.hue+S.hoff)%360+360)%360, 40, 100, (A.bass*0.4+A.rms*0.3)*P.energy*12);
  rect(0,0,W,H); blendMode(BLEND); pop();
}

function buildLUT(style, hue, seed){
  const L = new Uint8ClampedArray(768);
  const c2 = v => v<0?0:v>1?1:v;
  const hsv = (h,s,v)=>{ h=((h%360)+360)%360/60; const c=v*s, x=c*(1-Math.abs(h%2-1)), m=v-c; let r,g,b;
    if(h<1){r=c;g=x;b=0;} else if(h<2){r=x;g=c;b=0;} else if(h<3){r=0;g=c;b=x;} else if(h<4){r=0;g=x;b=c;} else if(h<5){r=x;g=0;b=c;} else {r=c;g=0;b=x;}
    return [r+m,g+m,b+m]; };
  let cool, warm;
  if (style==='ocean-wave'){ cool=hsv(hue+185,0.72,0.26); warm=hsv(hue+165,0.60,0.60); }
  else if (style==='aurora'){ cool=hsv(hue+300,0.60,0.90); warm=hsv(hue+120,0.70,0.95); }
  else if (style==='ink-shear'){ cool=hsv(hue+205,0.28,0.14); warm=hsv(hue,0.10,0.92); }
  else { cool=hsv(hue+195,0.45,0.60); warm=hsv(hue,0.58,0.95); }
  const heat=[[0.02,0.02,0.12],[0.28,0.02,0.42],[0.72,0.13,0.28],[0.96,0.44,0.12],[1.0,0.82,0.24],[1.0,1.0,0.92]];
  for (let i=0;i<256;i++){ const t=i/255; let r,g,b;
    if (style==='thermal'){ const f=t*5, k=Math.min(4,f|0), fr=f-k, a=heat[k], bb=heat[k+1]; r=a[0]+(bb[0]-a[0])*fr; g=a[1]+(bb[1]-a[1])*fr; b=a[2]+(bb[2]-a[2])*fr; }
    else if (style==='ink-shear'){ const q=ss((t-0.5)*1.6+0.5); r=cool[0]+(warm[0]-cool[0])*q; g=cool[1]+(warm[1]-cool[1])*q; b=cool[2]+(warm[2]-cool[2])*q; }
    else { const q=ss(t); r=cool[0]+(warm[0]-cool[0])*q; g=cool[1]+(warm[1]-cool[1])*q; b=cool[2]+(warm[2]-cool[2])*q;
      if (style!=='ocean-wave' && style!=='aurora'){ const hi=Math.exp(-((t-0.5)*(t-0.5))/0.012); r+=hi*0.16; g+=hi*0.15; b+=hi*0.12; } }
    L[i*3]=c2(r)*255; L[i*3+1]=c2(g)*255; L[i*3+2]=c2(b)*255;
  }
  return L;
}
